        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DELIST_RSN_NM", txb_DELIST_RSN_DSC.getValue());
        // param_dts_mst.NameString(param_dts_mst.RowPosition, "DELIST_RSN_NM") = dts_Rsn.NameString(dts_Rsn.RowPosition, "NAME")  ;

        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 15;
    const hgt = 785 + 40;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

